import static org.mockito.Mockito.*;

/** Illustrative scene: actual label/tile renderer, mocked projection and item silhouettes. */
public final class AppearancePreview
{
    public static void main(String[] args) throws Exception
    {
        Path output = Path.of(args[0]);
        Files.createDirectories(output);
        render(output.resolve("appearance-100.png"), 1);
        render(output.resolve("appearance-150.png"), 1.5);
    }

    private static void render(Path path, double scale) throws Exception
    {
        BufferedImage image = new BufferedImage((int) (1115 * scale), (int) (370 * scale), BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.scale(scale, scale);
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(new Color(28, 29, 32));
        graphics.fillRect(0, 0, 1115, 370);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 19));
        graphics.setColor(Color.WHITE);
        graphics.drawString("My Drops - appearance preview", 20, 30);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
        graphics.setColor(new Color(190, 190, 190));
        graphics.drawString("Illustrative scene. Item shapes are placeholders; labels and tile fills use the plugin renderer.", 20, 53);
        panel(graphics, 20, "Default: item outline", 0);
        panel(graphics, 295, "Names and background", 1);
        panel(graphics, 570, "GIM group items (includes loot)", 2);
        panel(graphics, 845, "Own drop + GIM group item", 3);
        graphics.setColor(new Color(190, 190, 190));
        graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
        graphics.drawString("Cyan: your deliberate drops. Magenta: GIM group-owned items, including loot. No dropper names or Party setup.", 20, 327);
        graphics.drawString("Each color includes opacity. Optional item names can duplicate the core Ground Items labels. Mixed tiles use your own fill color.", 20, 348);
        graphics.dispose();
        ImageIO.write(image, "png", path.toFile());
    }

    private static void panel(Graphics2D canvas, int x, String title, int mode)
    {
        Graphics2D graphics = (Graphics2D) canvas.create(x, 75, 250, 225);
        graphics.setColor(new Color(54, 59, 48));
        graphics.fillRect(0, 0, 250, 225);
        graphics.setColor(new Color(65, 70, 57));
        for (int y = 35; y < 225; y += 26) { graphics.drawLine(0, y, 250, y - 22); }
        graphics.setColor(Color.WHITE);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
        graphics.drawString(title, 10, 21);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));

        Client client = mock(Client.class);
        when(client.getLocalPlayer()).thenReturn(mock(Player.class));
        WorldView view = mock(WorldView.class);
        when(view.getPlane()).thenReturn(0);
        Tile tile = mock(Tile.class);
        when(tile.getPlane()).thenReturn(0);
        ItemLayer layer = mock(ItemLayer.class);
        when(layer.getWorldView()).thenReturn(view);
        when(tile.getItemLayer()).thenReturn(layer);
        when(layer.getCanvasLocation()).thenReturn(new Point(125, 153));
        when(layer.getCanvasTilePoly()).thenReturn(new Polygon(new int[]{125, 210, 125, 40}, new int[]{116, 153, 190, 153}, 4));
        when(layer.getCanvasTextLocation(any(Graphics2D.class), anyString(), eq(20)))
            .thenAnswer(call -> new Point(125 - graphics.getFontMetrics().stringWidth(call.getArgument(1)) / 2, 112));

        MyDropsConfig config = new MyDropsConfig()
        {
            @Override public boolean outline() { return mode != 1; }
            @Override public boolean text() { return mode != 0; }
            @Override public boolean tileFill() { return mode >= 2; }
            @Override public boolean groupItems() { return mode >= 2; }
        };
        MyDropsPlugin plugin = new MyDropsPlugin();
        plugin.filter.setExtras("");
        TileItem food = item(plugin, tile, "Shark", ResourceFilter.FOOD, 1, mode == 2);
        TileItem ammo = item(plugin, tile, "Dragon dart(p++)", ResourceFilter.AMMO, 200, mode >= 2);
        Polygon foodShape = new Polygon(new int[]{80, 108, 121, 111, 88, 70}, new int[]{148, 134, 147, 158, 161, 157}, 6);
        Polygon ammoShape = new Polygon(new int[]{145, 164, 170, 151}, new int[]{159, 140, 145, 164}, 4);
        graphics.setColor(new Color(160, 159, 130));
        graphics.fill(foodShape);
        graphics.setColor(new Color(145, 80, 65));
        graphics.fill(ammoShape);
        ModelOutlineRenderer outlines = mock(ModelOutlineRenderer.class);
        doAnswer(call ->
        {
            graphics.setColor(call.getArgument(3));
            graphics.setStroke(new BasicStroke(call.getArgument(2, Integer.class).floatValue()));
            graphics.draw(call.getArgument(1) == food ? foodShape : ammoShape);
            return null;
        }).when(outlines).drawOutline(eq(layer), any(TileItem.class), anyInt(), any(Color.class), anyInt());
        new MyDropsOverlay(client, plugin, config, outlines).render(graphics);
        graphics.setColor(new Color(220, 220, 210));
        String caption = mode == 2 ? "Group-owned resources / loot" : mode == 3 ? "Cyan own fill wins on mixed tile" : "Two of your dropped items";
        graphics.drawString(caption, (250 - graphics.getFontMetrics().stringWidth(caption)) / 2, 210);
        graphics.dispose();
    }

    private static TileItem item(MyDropsPlugin plugin, Tile tile, String name, int categories, int quantity, boolean group)
    {
        TileItem item = mock(TileItem.class);
        when(item.getOwnership()).thenReturn(group ? TileItem.OWNERSHIP_GROUP : TileItem.OWNERSHIP_SELF);
        if (group) { plugin.groupItems.put(item, tile); }
        else { plugin.tracker.tracked().put(item, tile); }
        MyDropsPlugin.Label label = new MyDropsPlugin.Label(name, name, categories);
        label.quantity(quantity);
        plugin.labels.put(item, label);
        return item;
    }
}

package com.mydrops;

import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DropTrackerTest
{
    private DropTracker tracker;
    private WorldView view;
    private Tile tile;
    private TileItem item;
    private final WorldPoint point = new WorldPoint(3200, 3200, 0);

    @Before public void setup()
    {
        tracker = new DropTracker(); view = mock(WorldView.class); tile = tile(view, point); item = item(100, TileItem.OWNERSHIP_SELF);
    }
    private Tile tile(WorldView world, WorldPoint location)
    {
        Tile result = mock(Tile.class); ItemLayer layer = mock(ItemLayer.class);
        when(result.getWorldLocation()).thenReturn(location); when(result.getItemLayer()).thenReturn(layer); when(layer.getWorldView()).thenReturn(world);
        return result;
    }
    private TileItem item(int id, int owner)
    {
        TileItem result = mock(TileItem.class); when(result.getId()).thenReturn(id); when(result.getOwnership()).thenReturn(owner); return result;
    }
    private void intent(int count, int quantity, int tick) { tracker.intent(100, count, quantity, tick, view, point); }
    private void ground(int amount, int tick) { tracker.ground(item, tile, amount, tick, point); }

    @Test public void needsIntent() { ground(1, 1); tracker.confirm(1, id -> 0); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void needsGroundChange() { intent(5, 1, 1); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void needsInventoryLoss() { intent(5, 1, 1); ground(1, 1); tracker.confirm(1, id -> 5); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void confirmsDrop() { intent(5, 1, 1); ground(1, 1); tracker.confirm(1, id -> 4); assertSame(tile, tracker.tracked().get(item)); }
    @Test public void inventoryCanUpdateBeforeGroundEvent() { intent(5, 1, 1); int remaining = 4; ground(1, 1); tracker.confirm(1, id -> remaining); assertEquals(1, tracker.tracked().size()); }
    @Test public void rejectsOtherOwners()
    {
        for (int owner : new int[]{TileItem.OWNERSHIP_NONE, TileItem.OWNERSHIP_OTHER, TileItem.OWNERSHIP_GROUP})
        {
            tracker.clear(); intent(5, 1, 1); tracker.ground(item(100, owner), tile, 1, 1, point); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty());
        }
    }
    @Test public void rejectsOtherWorldView() { intent(5, 1, 1); tracker.ground(item, tile(mock(WorldView.class), point), 1, 1, point); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void rejectsDistantTile() { intent(5, 1, 1); tracker.ground(item, tile(view, new WorldPoint(3210, 3200, 0)), 1, 1, point); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void acceptsCurrentPlayerTileAfterMovement()
    {
        WorldPoint moved = new WorldPoint(3201, 3200, 0); intent(5, 1, 1); tracker.ground(item, tile(view, moved), 1, 1, moved); tracker.confirm(1, id -> 4); assertEquals(1, tracker.tracked().size());
    }
    @Test public void rejectsWrongId() { intent(5, 1, 1); tracker.ground(item(101, TileItem.OWNERSHIP_SELF), tile, 1, 1, point); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void expiresWithoutRevival() { intent(5, 1, 1); ground(1, 1); tracker.confirm(5, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void newClicksDoNotRenewOldCandidates() { intent(5, 1, 1); ground(1, 1); intent(5, 1, 4); tracker.confirm(5, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void handlesRapidSameItemDrops()
    {
        intent(5, 1, 1); intent(5, 1, 1); ground(1, 1); TileItem second = item(100, TileItem.OWNERSHIP_SELF);
        tracker.ground(second, tile, 1, 1, point); tracker.confirm(1, id -> 3); assertEquals(2, tracker.tracked().size());
    }
    @Test public void rejectsAmbiguousLootAndDrop()
    {
        intent(5, 1, 1); ground(1, 1); tracker.confirm(1, id -> 5);
        intent(5, 1, 2); tracker.ground(item(100, TileItem.OWNERSHIP_SELF), tile, 1, 2, point);
        tracker.confirm(2, id -> 4); assertTrue(tracker.tracked().isEmpty());
    }
    @Test public void cannotSpendMoreThanClickedQuantity() { intent(10, 1, 1); ground(2, 1); tracker.confirm(1, id -> 8); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void quantityIncreaseMatchesDeltaNotStackTotal() { intent(50, 50, 1); when(item.getQuantity()).thenReturn(150); ground(50, 1); tracker.confirm(1, id -> 0); assertEquals(1, tracker.tracked().size()); }
    @Test public void ignoresQuantityDecrease() { intent(5, 1, 1); ground(-1, 1); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void despawnBeforeConfirmationCancelsCandidate() { intent(5, 1, 1); ground(1, 1); tracker.remove(item); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void despawnRemovesConfirmedItem() { confirmsDrop(); tracker.remove(item); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void consumedIntentCannotMarkLaterLoot() { confirmsDrop(); tracker.remove(item); ground(1, 2); tracker.confirm(2, id -> 3); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void nonDropActionCancelsIntent() { intent(5, 1, 1); ground(1, 1); tracker.cancel(100); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void resetClearsPendingAndConfirmed() { confirmsDrop(); intent(5, 1, 1); tracker.clear(); ground(1, 1); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void worldViewUnloadClearsPendingAndConfirmed() { confirmsDrop(); intent(5, 1, 1); tracker.unload(view); ground(1, 1); tracker.confirm(1, id -> 4); assertTrue(tracker.tracked().isEmpty()); }
    @Test public void trackingStaysBounded()
    {
        for (int i = 0; i < 300; i++)
        {
            tracker.intent(i, 1, 1, i, view, point); tracker.ground(item(i, TileItem.OWNERSHIP_SELF), tile, 1, i, point); tracker.confirm(i, id -> 0);
        }
        assertEquals(DropTracker.MAX_TRACKED, tracker.tracked().size());
    }
    @Test public void candidateOverflowFailsClosed()
    {
        intent(100, 100, 1);
        for (int i = 0; i < 29; i++) { tracker.ground(item(100, TileItem.OWNERSHIP_SELF), tile, 1, 1, point); }
        tracker.confirm(1, id -> 72); assertTrue(tracker.tracked().isEmpty());
    }
}

package com.mydrops;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.swing.SwingUtilities;
import net.runelite.client.RuneLite;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.devtools.DevToolsPlugin;

public final class MyDropsLauncher
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(MyDropsPlugin.class);
        List<String> arguments = new ArrayList<>(Arrays.asList(args));
        if (!arguments.contains("--developer-mode")) { arguments.add("--developer-mode"); }
        RuneLite.main(arguments.toArray(new String[0]));
        PluginManager pluginManager = RuneLite.getInjector().getInstance(PluginManager.class);
        DevToolsPlugin devTools = pluginManager.getPlugins().stream()
            .filter(DevToolsPlugin.class::isInstance)
            .map(DevToolsPlugin.class::cast)
            .findFirst().orElse(null);
        boolean discovered = devTools != null;
        if (devTools == null)
        {
            try
            {
                devTools = pluginManager.loadPlugins(Collections.<Class<?>>singletonList(DevToolsPlugin.class), null)
                    .stream().filter(DevToolsPlugin.class::isInstance)
                    .map(DevToolsPlugin.class::cast).findFirst().orElse(null);
            }
            catch (Exception ex)
            {
                System.err.println("My Drops dev tools: load failed: " + ex.getClass().getSimpleName());
            }
        }
        System.out.println("My Drops dev tools: assertions=" + RuneLite.class.desiredAssertionStatus()
            + " launcherManaged=" + (RuneLiteProperties.getLauncherVersion() != null)
            + " discovered=" + discovered
            + " loaded=" + (devTools != null)
            + " enabled=" + (devTools != null && pluginManager.isPluginEnabled(devTools))
            + " active=" + (devTools != null && pluginManager.isPluginActive(devTools)));
        if (devTools != null && !pluginManager.isPluginActive(devTools))
        {
            pluginManager.setPluginEnabled(devTools, true);
            DevToolsPlugin selectedDevTools = devTools;
            SwingUtilities.invokeLater(() ->
            {
                try
                {
                    pluginManager.startPlugin(selectedDevTools);
                    System.out.println("My Drops dev tools: started=" + pluginManager.isPluginActive(selectedDevTools));
                }
                catch (Exception ex)
                {
                    System.err.println("My Drops dev tools: start failed: " + ex.getClass().getSimpleName());
                }
            });
        }
    }
}

