            assertTrue(reload.isReplaying());
        }
        assertTrue(reload.finish(330, 23).isEmpty());
        assertFalse(reload.isReplaying());
        reload.spawned(item(), tile, 330, 24);
        assertTrue(reload.finish(330, 24).isEmpty());
    }

